Given an array arr[] and a positive integer k, the task is to count all pairs (i, j) such that i < j and absolute value of (arr[i] - arr[j]) is equal to k. Examples: Input: arr[] = [1, 4, 1, 4, 5], k = 3Output: 4Explanation: There are 4 pairs with absolute difference 3, the pairs are [1, 4], [1, 4], [1, 4] and [4, 1]Input: arr[] = [8, 16, 12, 16, 4, 0], k = 4Output: 5Explanation: There are 5 pairs with absolute difference 4, the pairs are [8, 12], [8, 4], [16, 12], [12, 16], [4, 0].Try It YourselfTable of Content[Naive Approach] Generating all pairs - O(n^2) Time and O(1) Space[Better Approach] Sorting and Two Pointer Technique - O(n*logn) Time and O(1) Space[Expected Approach] Using Hash Map or Dictionary – O(n) Time and O(n) Space[Naive Approach] Generating all pairs - O(n^2) Time and O(1) SpaceThe basic idea is to use two nested loops to generate all pairs in arr[]. For each pair, if the absolute difference is equal to k, increment the count by 1.
            C++

    // C++ Program to count all pairs with difference equal to k
// by generating all pairs

#include <iostream>
#include <vector>
using namespace std;

int countPairs(vector<int> &arr, int k) {
    int n = arr.size();
    int cnt = 0;

    // generate all possible pairs
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {

            // If absolute difference = k, then increment
            // count by 1
            if (abs(arr[i] - arr[j]) == k) {
                cnt += 1;
            }
        }
    }
    return cnt;
}

int main() {
    vector<int> arr = {1, 4, 1, 4, 5};
    int k = 3;

    cout << countPairs(arr, k);
    return 0;
}


